//! Replays every case of `tests/fixtures/golden.json` (generated by
//! `examples/gen_golden.rs`) through the IPC surface and checks, per case:
//!
//! 1. **Canonical equality:** the response parsed as JSON equals the stored
//!    `res` value (order-insensitive object comparison).
//! 2. **Raw byte equality:** the serialized response is byte-identical to
//!    the stored `res` text, which pins the key order (FROZEN §13: "The
//!    parity check compares both canonical JSON and raw key order").
//!
//! It also checks the file layout the mobile CI replay relies on: LF only,
//! one case per line, `req` in canonical (recursively key-sorted) form, a
//! header whose `count` matches, at least 12,000 cases and every op present.

use std::collections::BTreeMap;

use date_core::api::{self, Op};
use date_core::ErrorCode;
use serde_json::Value;

const FIXTURE: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/golden.json");

/// Compact JSON with object keys sorted recursively (the generator's form).
fn write_canonical(v: &Value, out: &mut String) {
    match v {
        Value::Object(map) => {
            let mut keys: Vec<&String> = map.keys().collect();
            keys.sort();
            out.push('{');
            for (i, k) in keys.into_iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push_str(&Value::String(k.clone()).to_string());
                out.push(':');
                write_canonical(&map[k], out);
            }
            out.push('}');
        }
        Value::Array(items) => {
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_canonical(item, out);
            }
            out.push(']');
        }
        scalar => out.push_str(&scalar.to_string()),
    }
}

fn excerpt(s: &str) -> String {
    s.chars().take(400).collect()
}

#[test]
fn golden_fixture_matches_engine_canonically_and_byte_for_byte() {
    let text = std::fs::read_to_string(FIXTURE).expect("read golden.json");
    assert!(!text.contains('\r'), "golden.json must be LF-only");
    assert!(
        text.ends_with("\n]}\n"),
        "golden.json must end with \"]}}\\n\""
    );

    let doc: Value = serde_json::from_str(&text).expect("golden.json is valid JSON");
    assert_eq!(doc["version"], 1);
    assert_eq!(doc["engine"], date_core::ENGINE_VERSION);
    let cases = doc["cases"].as_array().expect("cases array");
    assert_eq!(
        doc["count"].as_u64(),
        Some(cases.len() as u64),
        "header count"
    );
    assert!(
        cases.len() >= 12_000,
        "expected >= 12,000 golden cases, got {}",
        cases.len()
    );

    // Header line, one line per case, closing line.
    let lines: Vec<&str> = text.split('\n').collect();
    assert_eq!(lines.len(), cases.len() + 3, "one case per line");
    assert!(lines[0].starts_with("{\"version\":1,") && lines[0].ends_with("\"cases\":["));
    assert_eq!(lines[cases.len() + 1], "]}");

    let mut per_op: BTreeMap<&str, (usize, usize)> = BTreeMap::new();
    let mut canonical_failures: Vec<String> = Vec::new();
    let mut raw_failures: Vec<String> = Vec::new();

    for (idx, case) in cases.iter().enumerate() {
        let line = lines[idx + 1];
        let body = if idx + 1 < cases.len() {
            line.strip_suffix(',').expect("case line ends with a comma")
        } else {
            line
        };
        let op_name = case["op"].as_str().expect("op string");
        let op = Op::from_name(op_name).unwrap_or_else(|| panic!("case #{idx}: unknown op"));
        let req = &case["req"];

        let mut prefix = format!("{{\"op\":\"{op_name}\",\"req\":");
        write_canonical(req, &mut prefix);
        prefix.push_str(",\"res\":");
        assert!(
            body.starts_with(&prefix) && body.ends_with('}'),
            "case #{idx}: line layout or non-canonical req: {}",
            excerpt(body)
        );
        let stored_raw = &body[prefix.len()..body.len() - 1];

        let response = api::call(op, req);
        let entry = per_op.entry(op.name()).or_default();
        match response.error() {
            None => entry.0 += 1,
            Some(e) => {
                assert_ne!(
                    e.code,
                    ErrorCode::InvalidRequest,
                    "case #{idx}: invalid_request is not part of the parity contract"
                );
                entry.1 += 1;
            }
        }

        let actual_value = serde_json::to_value(&response).expect("serialize response");
        if actual_value != case["res"] && canonical_failures.len() < 5 {
            canonical_failures.push(format!(
                "case #{idx} {op_name} req={}\n  want={}\n  got ={}",
                excerpt(&req.to_string()),
                excerpt(stored_raw),
                excerpt(&actual_value.to_string())
            ));
        }
        let actual_raw = serde_json::to_string(&response).expect("serialize response");
        if actual_raw != stored_raw && raw_failures.len() < 5 {
            raw_failures.push(format!(
                "case #{idx} {op_name}\n  want={}\n  got ={}",
                excerpt(stored_raw),
                excerpt(&actual_raw)
            ));
        }
    }

    for (op, (ok, err)) in &per_op {
        println!("GOLDEN op={op} ok={ok} err={err}");
    }
    assert!(
        canonical_failures.is_empty(),
        "canonical mismatches (first {}):\n{}",
        canonical_failures.len(),
        canonical_failures.join("\n")
    );
    assert!(
        raw_failures.is_empty(),
        "raw byte mismatches (first {}):\n{}",
        raw_failures.len(),
        raw_failures.join("\n")
    );
    for op in Op::ALL {
        let (ok, err) = per_op.get(op.name()).copied().unwrap_or_default();
        assert!(ok > 0 && err > 0, "{}: needs ok and error cases", op.name());
    }
}
